/**
 * Queueable job that re-rates up to 50,000 Accounts in chained batches of 200.
 *
 * Each execution processes the first 200 Ids of its list (one SOQL query,
 * one DML statement). If Ids remain, the job hands off the remainder to the
 * next AccountScoringJob.
 *
 * Chaining is done via a Finalizer rather than a direct System.enqueueJob
 * call from within execute(). A Finalizer always runs in its own, fresh
 * asynchronous transaction (in both production and test execution), which
 * avoids accumulating "stack depth" across a long chain of jobs - something
 * that otherwise throws System.AsyncException: Maximum stack depth has been
 * reached once a chain gets more than a handful of links deep, especially in
 * Developer Edition / scratch orgs.
 *
 * When execute() is invoked directly (not through the real async framework -
 * for example a unit test calling `new AccountScoringJob(ids).execute(null)`),
 * the platform-supplied QueueableContext is null, so there is no genuine
 * AsyncApexJob to attach a Finalizer to. In that case we fall back to a plain
 * System.enqueueJob call for the remainder.
 */
public class AccountScoringJob implements Queueable {

    public static final Integer BATCH_SIZE = 200;
    public static final Decimal HOT_THRESHOLD = 1000000;
    public static final Decimal WARM_THRESHOLD = 100000;

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null) ? new List<Id>() : accountIds;
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer total = accountIds.size();
        Integer splitAt = Math.min(BATCH_SIZE, total);

        List<Id> currentBatch = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        for (Integer i = 0; i < total; i++) {
            if (i < splitAt) {
                currentBatch.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        // One SOQL query per execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue, Rating
            FROM Account
            WHERE Id IN :currentBatch
        ];

        for (Account acc : accounts) {
            Decimal revenue = acc.AnnualRevenue;
            if (revenue != null && revenue >= HOT_THRESHOLD) {
                acc.Rating = 'Hot';
            } else if (revenue != null && revenue >= WARM_THRESHOLD) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
        }

        // One DML statement per execution.
        if (!accounts.isEmpty()) {
            update accounts;
        }

        // Chain the next batch, even while a test is running, so the whole
        // set of Ids is processed by the time Test.stopTest() completes.
        if (!remainingIds.isEmpty()) {
            if (context != null) {
                // Genuine asynchronous execution: defer the re-enqueue to a
                // Finalizer so each hop starts a brand new transaction and
                // the platform's chain stack-depth never accumulates, no
                // matter how many batches remain.
                System.attachFinalizer(new ChainFinalizer(remainingIds));
            } else {
                // execute() was invoked directly (no real async context to
                // attach a Finalizer to) - just enqueue the next job.
                System.enqueueJob(new AccountScoringJob(remainingIds));
            }
        }
    }

    /**
     * Enqueues the first job in the chain for up to 50,000 account Ids.
     * Returns the enqueued job's Id, or null if accountIds is null/empty.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    /**
     * Runs in its own fresh asynchronous transaction after the triggering
     * AccountScoringJob completes, and simply enqueues the next link in the
     * chain. This indirection is what allows chains far longer than the
     * platform's queueable stack-depth limit to complete successfully,
     * including within a single Test.startTest()/Test.stopTest() block.
     */
    private class ChainFinalizer implements Finalizer {
        private List<Id> remainingIds;

        ChainFinalizer(List<Id> remainingIds) {
            this.remainingIds = remainingIds;
        }

        public void execute(FinalizerContext ctx) {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }
}
