/**
 * Batchable worker that performs the actual deletion of old
 * FB_Integration_Log__c records in bulk-safe chunks.
 *
 * Rules:
 *  - Logs with Level__c != 'ERROR' (including blank) are deleted once older than 30 days.
 *  - Logs with Level__c = 'ERROR' are kept until older than 180 days.
 */
public class LogPurgeBatch implements Database.Batchable<SObject> {

    public Database.QueryLocator start(Database.BatchableContext bc) {
        DateTime cutoffStandard = DateTime.now().addDays(-30);
        DateTime cutoffError = DateTime.now().addDays(-180);

        String query =
            'SELECT Id FROM FB_Integration_Log__c ' +
            'WHERE ((Level__c != \'ERROR\' OR Level__c = null) AND CreatedDate < :cutoffStandard) ' +
            'OR (Level__c = \'ERROR\' AND CreatedDate < :cutoffError)';

        return Database.getQueryLocator(query);
    }

    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        delete scope;
    }

    public void finish(Database.BatchableContext bc) {
    }
}
