/**
 * After-update trigger on Case.
 *
 * For every case that transitions from not-closed to closed and has a
 * contact, we kick off a CaseSurveyJob (Queueable) that creates a CSAT
 * survey Task. Each newly-closed case gets its own CaseSurveyJob instance,
 * enqueued directly from the trigger, so that a failure processing one
 * case's job can never affect any other case.
 *
 * The loop over Trigger.new/Trigger.oldMap is bulk-safe and handles any
 * batch size uniformly - whether a handful of cases closed from a list
 * view, or up to 200 closed at once by the nightly API cleanup.
 */
trigger CaseTrigger on Case (after update) {

    for (Case newCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(newCase.Id);

        if (newCase.IsClosed && !oldCase.IsClosed) {
            System.enqueueJob(new CaseSurveyJob(newCase.Id));
        }
    }
}
