/**
 * Trigger Action for the Trigger Actions Framework (TAF) enforcing the rule:
 * two Contacts belonging to the same Account may not share an email address
 * (compared case-insensitively). Contacts without an Account or without an
 * Email are not checked.
 *
 * - Record-level errors are added via addError so unaffected records in the
 *   same save are unaffected (partial save behavior).
 * - Within a single save, the first Contact claiming an Account+Email
 *   combination wins; later ones in the list are rejected.
 * - On update, only Contacts whose Email or AccountId changed are evaluated,
 *   and a Contact is never compared against its own prior value.
 * - Bulk-safe: at most one SOQL query is issued per trigger execution.
 */
public with sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        enforce((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        enforce((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    private void enforce(List<Contact> newContacts, List<Contact> oldContacts) {
        Map<Id, Contact> oldById = new Map<Id, Contact>();
        if (oldContacts != null) {
            for (Contact oldC : oldContacts) {
                oldById.put(oldC.Id, oldC);
            }
        }

        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();

        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            if (oldContacts != null) {
                Contact oldC = oldById.get(c.Id);
                Boolean emailChanged = oldC == null || oldC.Email != c.Email;
                Boolean accountChanged = oldC == null || oldC.AccountId != c.AccountId;
                if (!emailChanged && !accountChanged) {
                    // Neither relevant field changed; do not re-check legacy duplicates.
                    continue;
                }
            }

            candidates.add(c);
            accountIds.add(c.AccountId);
        }

        if (candidates.isEmpty()) {
            return;
        }

        // Single bulk-safe query covering all candidates' Accounts.
        Map<String, Set<Id>> existingKeyToIds = new Map<String, Set<Id>>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email != null
        ]) {
            String key = buildKey(existing.AccountId, existing.Email);
            Set<Id> ids = existingKeyToIds.get(key);
            if (ids == null) {
                ids = new Set<Id>();
                existingKeyToIds.put(key, ids);
            }
            ids.add(existing.Id);
        }

        Set<String> acceptedKeysInBatch = new Set<String>();

        for (Contact c : candidates) {
            String key = buildKey(c.AccountId, c.Email);

            Boolean conflictsWithExistingRecord = false;
            Set<Id> existingIds = existingKeyToIds.get(key);
            if (existingIds != null) {
                for (Id existingId : existingIds) {
                    if (existingId != c.Id) {
                        conflictsWithExistingRecord = true;
                        break;
                    }
                }
            }

            if (conflictsWithExistingRecord || acceptedKeysInBatch.contains(key)) {
                c.addError(DUPLICATE_ERROR_MESSAGE);
            } else {
                acceptedKeysInBatch.add(key);
            }
        }
    }

    private String buildKey(Id accountId, String email) {
        return accountId + '|' + email.toLowerCase();
    }
}
